Input: {"question": "What sport is Wayne Jones associated with?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0320-2fdeaaf15ee6:d00", "start": 0, "end": 40, "text": "Slam of darts for an extra year in 2012."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0320-2fdeaaf15ee6:d00", "start": 41, "end": 88, "text": "He was beaten by James Wade in the semi finals."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0320-2fdeaaf15ee6:d00", "start": 89, "end": 180, "text": "In 2012 he reached the last 16 of the PDC World Championship for the first time since 2006."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0320-2fdeaaf15ee6:d00", "start": 181, "end": 304, "text": "He comfortably beat Scott MacKenzie and Roland Scholten, before being whitewashed, 0–4, to defending champion Adrian Lewis."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0320-2fdeaaf15ee6:d00", "start": 305, "end": 467, "text": "At the Dutch Darts Masters, Jones produced an upset by beating Phil Taylor 6–5 en route to the quarter-finals, before losing to Paul Nicholson in the semi-finals."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0320-2fdeaaf15ee6:d00", "start": 468, "end": 566, "text": "After all 33 ProTour events of 2012 had been played, Jones was 32nd in the Order of Merit, gaining"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0320-2fdeaaf15ee6:d01", "start": 0, "end": 112, "text": "Wayne Jones (snooker player) Wayne Jones (born December 24, 1959) is a former Welsh professional snooker player."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0320-2fdeaaf15ee6:d01", "start": 113, "end": 218, "text": "Despite never breaking into the top 16, he reached the last 16 and quarter-finals of many ranking events."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0320-2fdeaaf15ee6:d01", "start": 219, "end": 395, "text": "His most notable run was to the final of the 1989 Classic with victories over the likes of Jimmy White, where he lost to Doug Mountjoy 11–13, despite at one stage leading 11–9."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0320-2fdeaaf15ee6:d01", "start": 396, "end": 578, "text": "He qualified for the World Championship on four occasions, but only ever progressed beyond the first round once, in 1989, with a 10–9 victory over Neal Foulds, but was beaten 13–3 by"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0320-2fdeaaf15ee6:d02", "start": 0, "end": 135, "text": "career came when he was aged just 24, when on 4 November 1972 he fell to the ground clutching his knee during a game against Brentford."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0320-2fdeaaf15ee6:d02", "start": 136, "end": 309, "text": "It was initially believed to be a cartilage injury, but it later emerged that he had a previously undiagnosed arthritic condition that meant he was never able to play again."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0320-2fdeaaf15ee6:d02", "start": 310, "end": 497, "text": "After his playing career had reached a premature end, Jones trained initially as a sports physiotherapist and later as a coach and continued working within football in various capacities."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0320-2fdeaaf15ee6:d02", "start": 498, "end": 584, "text": "In December 1977 he was appointed as Shrewsbury Town's physio, and in 1983 he returned"}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0320-2fdeaaf15ee6:d03", "start": 0, "end": 671, "text": "Fu Marcos Dayao Marcus Campbell Marcus Owen Marek Kenny Marek Slomianowski Mareks Cipsts Maria Catalano Maria Paul-Bennett Marian Kraus Marian Poole Marianne Williams Marianyela Palacios Mariia Shevchenko Marinus Teerling Mario Abela Mario Amza Mario Basile Mario Bodlos Mario Brincat Mario Geudens Mario Hautekeete Mario Hildred Mario Laus Mario Morra Mario Paun Mario Van Herk Mario Veltman Mario Wehrmann Mario-Zeljo Milosevic Maris Volajs Marissa Du Mark Allen Mark Anthony Taylor Mark Ball Mark Bell Mark Bennett Mark Boyd Mark Boyle Mark Buteneers Mark Cackett Mark Canovan Mark Carrington Mark Craven Mark Currie Mark Davies Mark Davis Mark Dooley Mark Fenton Mark"}, "D5S1": {"document_number": 5, "doc_id": "ramdocs-0320-2fdeaaf15ee6:d04", "start": 0, "end": 120, "text": "more last-32 runs ensured that Jones would finish the season in the highest position of his career , 33rd in the world ."}, "D5S2": {"document_number": 5, "doc_id": "ramdocs-0320-2fdeaaf15ee6:d04", "start": 121, "end": 337, "text": "Now an established top-64 player , Jones reached the quarter-final of the 2000 Welsh Open , defeating Jamie Burnett , Jimmy Michie and Drew Henry before losing 1–5 to Higgins , who would go on to win the tournament ."}, "D5S3": {"document_number": 5, "doc_id": "ramdocs-0320-2fdeaaf15ee6:d04", "start": 338, "end": 462, "text": "The highlight of season 2000/2001 for Jones was a run to the last 16 of the 2000 China Open ; there , he lost 3–5 to Henry ."}, "D5S4": {"document_number": 5, "doc_id": "ramdocs-0320-2fdeaaf15ee6:d04", "start": 463, "end": 510, "text": "After reaching the last 32 of the 2002 Scottish"}}, "original_cards": [{"doc_id": "ramdocs-0320-2fdeaaf15ee6:d00", "card_id": "ramdocs-0320-2fdeaaf15ee6:d00:c0", "entity": "Wayne Jones", "scope": "sport", "claim": "Wayne Jones is associated with darts.", "answer": "darts", "quote": "Slam of darts for an extra year in 2012. He was beaten by James Wade in the semi finals. In 2012 he reached the last 16 of the PDC World Championship for the first time since 2006. He comfortably beat Scott MacKenzie and Roland Scholten, before being whitewashed, 0–4, to defending champion Adrian Lewis.", "original_document_number": 1}, {"doc_id": "ramdocs-0320-2fdeaaf15ee6:d01", "card_id": "ramdocs-0320-2fdeaaf15ee6:d01:c0", "entity": "Wayne Jones", "scope": "sport", "claim": "Wayne Jones is associated with snooker.", "answer": "snooker", "quote": "Wayne Jones (snooker player) Wayne Jones (born December 24, 1959) is a former Welsh professional snooker player.", "original_document_number": 2}, {"doc_id": "ramdocs-0320-2fdeaaf15ee6:d02", "card_id": "ramdocs-0320-2fdeaaf15ee6:d02:c0", "entity": "Wayne Jones", "scope": "sport", "claim": "Wayne Jones is associated with football.", "answer": "football", "quote": "After his playing career had reached a premature end, Jones trained initially as a sports physiotherapist and later as a coach and continued working within football in various capacities. In December 1977 he was appointed as Shrewsbury Town's physio, and in 1983 he returned", "original_document_number": 3}, {"doc_id": "ramdocs-0320-2fdeaaf15ee6:d04", "card_id": "ramdocs-0320-2fdeaaf15ee6:d04:c0", "entity": "Wayne Jones", "scope": "sport", "claim": "Wayne Jones is associated with snooker.", "answer": "Snooker", "quote": "more last-32 runs ensured that Jones would finish the season in the highest position of his career , 33rd in the world . Now an established top-64 player , Jones reached the quarter-final of the 2000 Welsh Open , defeating Jamie Burnett , Jimmy Michie and Drew Henry before losing 1–5 to Higgins , who would go on to win the tournament . The highlight of season 2000/2001 for Jones was a run to the last 16 of the 2000 China Open ; there , he lost 3–5 to Henry .", "original_document_number": 5}], "current_answers": ["darts", "snooker", "football"], "candidate_answers": [{"candidate_id": "R0", "answer": "darts", "origin": "initial"}, {"candidate_id": "R1", "answer": "snooker", "origin": "initial"}, {"candidate_id": "R2", "answer": "football", "origin": "initial"}], "requested_slot_hint": "sport"}
